<?php require '../../config/database.php';require '../../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$_POST['status']??'';$pay=$_POST['payment_status']??'';$id=(int)($_POST['id']??0);if(in_array($s,['pending','confirmed','cancelled','completed'],true)&&in_array($pay,['unpaid','paid','refunded'],true)){[$ok,$message]=change_booking_status($pdo,$id,$s);if($ok){$pdo->prepare('UPDATE bookings SET payment_status=? WHERE id=?')->execute([$pay,$id]);flash(strpos($message, 'could not be sent') !== false ? 'error' : 'success', $message . ' Payment status saved; availability is based on the current reservations.');}else{flash('error',$message);}}else{flash('error','Invalid booking or payment status.');}header('Location: '.url('admin/bookings/index.php'));exit;}$bookings=$pdo->query("SELECT b.*,u.name guest,r.name room_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id ORDER BY b.created_at DESC")->fetchAll();$page_title='Manage Bookings';include '../../includes/header.php';?><div class="container page-hero"><h1>Bookings</h1><p class="muted">Manage reservation and payment status.</p></div><section style="padding-top:5px"><div class="container"><div class="table-wrap"><table class="table"><thead><tr><th>Reference</th><th>Guest</th><th>Room</th><th>Stay dates</th><th>Booked on</th><th>Total</th><th>Update</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><a href="<?=url('booking/view.php?id='.$b['id'])?>"><strong><?=e($b['reference_no'])?></strong></a></td><td><?=e($b['guest'])?></td><td><?=e($b['room_name'])?></td><td><?=e($b['check_in'])?> → <?=e($b['check_out'])?></td><td><?=e(date('M j, Y',strtotime($b['created_at'])))?><small class="table-sub"><?=e(date('g:i A',strtotime($b['created_at'])))?></small></td><td>₱<?=number_format($b['total_amount'],2)?></td><td><form method="post" class="actions" data-confirm="Save these booking and payment status changes?" data-confirm-title="Update booking"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$b['id']?>"><select class="select" name="status" style="width:auto"><?php foreach(['pending','confirmed','cancelled','completed'] as $s):?><option <?=$b['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><select class="select" name="payment_status" style="width:auto"><?php foreach(['unpaid','paid','refunded'] as $s):?><option <?=$b['payment_status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-primary btn-sm">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include '../../includes/footer.php';?>